// Helper to normalize float operands and clamp arithmetic results.
// VU floats have no denormals, infinities or NaNs.
// Operands: denormals (exp 0) -> 0 (same sign), infinities (exp 0xFF) -> max float (0x7f7fffff).
// Arithmetic results: underflow -> 0 (same sign), overflow -> max float.
static inline float normalize(float f) {
    uint32_t u;
    std::memcpy(&u, &f, 4);
    if ((u & 0x7f800000) == 0) {
        // Denormal or zero
        uint32_t sign = u & 0x80000000;
        std::memcpy(&f, &sign, 4);
        return f;
    }
    if ((u & 0x7f800000) == 0x7f800000) {
        // Infinity
        uint32_t sign = u & 0x80000000;
        uint32_t val = sign | 0x7f7fffff;
        std::memcpy(&f, &val, 4);
        return f;
    }
    return f;
}

// For arithmetic results, we clamp underflows/overflows.
// This is effectively the same as normalize for the result bits.
static inline float clamp_arith(float f) {
    return normalize(f);
}

