    madda(vu, vf[25], vf[24][1]);           // 0xcc8 MADDAy.xyzw ACC, vf25, vf24y
    maddv(vu, 16, vf[26], vf[24][2]);       // 0xcd0 MADDz.xyzw vf16, vf26, vf24z
