void stage(VuState &vu) {
    // 0xda0: NOP                                IBNE vi10, vi0, 0xc08
    // vi0 is always 0. Jump if vi10 != 0.
    if (vu.vi[10] != 0) {
        vu.pc = 0xc08;
        return;
    }

    // 0xda8: NOP                                NOP   [delay slot of the branch above: executes before the jump, also when it is taken]
    // 0xdb0: NOP                                XGKICK vi2
    xgkick(vu, static_cast<uint32_t>(vu.vi[2]));

    // 0xdb8: NOP                                NOP
    // 0xdc0: NOP                                NOP   E
    // 0xdc8: NOP                                NOP   [delay slot of the program end]
    vu.pc = 0xffffffff;
}
