    if (branch_1890) {
        vu.pc = 0x6a8;
        return;
    }

    // 18a0: NOP                                IBEQ vi10, vi3, 0xa50
    // 18a8: NOP                                NOP   [delay slot always executes]
    bool branch_18a0 = (vu.vi[10] == vu.vi[3]);
