    if (branch_18c0) {
        vu.pc = 0x3530;
        return;
    }

    // 18d0: NOP                                IBEQ vi10, vi6, 0x1518
    // 18d8: NOP                                IADDIU vi5, vi0, 6   [delay slot always executes]
    bool branch_18d0 = (vu.vi[10] == vu.vi[6]);
    // Delay slot ALWAYS executes, modifying vi5 regardless of branch result
    vu.vi[5] = static_cast<int32_t>(static_cast<int16_t>(vu.vi[0] + 6));

    if (branch_18d0) {
        vu.pc = 0x1518;
        return;
    }

    // 18e0: NOP                                IBEQ vi10, vi7, 0x2ae0
    // 18e8: NOP                                NOP   [delay slot always executes]
    bool branch_18e0 = (vu.vi[10] == vu.vi[7]);
    // 18e8 is NOP

    if (branch_18e0) {
        vu.pc = 0x2ae0;
        return;
    }

