// Helper to normalize float operands as per VU1 rules
// Denormals (exp 0) -> 0.0 with sign
// Inf/NaN (exp 0xFF) -> Max float with sign
inline float normalize(float f) {
    uint32_t bits = *(uint32_t*)&f;
    int32_t exp = (bits >> 23) & 0xFF;
    int32_t sign = bits & 0x80000000;

    if (exp == 0) {
        // Denormal -> 0.0 of same sign
        return *(float*)&sign;
    }
    if (exp == 0xFF) {
        // Inf/NaN -> Max float of same sign
        // 0x7f7fffff is max positive float, 0xff7fffff is max negative float
        return (sign ? -3.40282347e+38f : 3.40282347e+38f) /* fixed 26 Oct: was a read from address 0x7f7fffff */;
    }
    return f;
}

// Helper to saturate arithmetic results as per VU1 rules
// Underflow (denormal result) -> 0.0 with sign
// Overflow (Inf result) -> Max float with sign
inline float saturate(float f) {
    uint32_t bits = *(uint32_t*)&f;
    int32_t exp = (bits >> 23) & 0xFF;
    int32_t sign = bits & 0x80000000;

    if (exp == 0) {
        return *(float*)&sign;
    }
    if (exp == 0xFF) {
        return (sign ? -3.40282347e+38f : 3.40282347e+38f) /* fixed 26 Oct: was a read from address 0x7f7fffff */;
    }
    return f;
}

// Helper to load a qword from memory into vf register
// Assumes mask is xyzw (all lanes) for this stage, but generalizable
inline void load_qword(VuState &vu, int vf_idx, int vi_idx, int32_t vi_val) {
    // vi_val is sign-extended 16-bit.
    // Memory is 1024 qwords. Address wraps at 1024 qwords.
    // vi holds qword index.
    int32_t addr_qword = vi_val & 0x3FF; // Wrap at 1024
    int32_t addr_byte = addr_qword * 16;

    // Load 16 bytes into vf[vf_idx]
    // vf lanes are x, y, z, w (floats)
    // Memory layout: x is first 4 bytes, then y, z, w
    std::memcpy(&vu.vf[vf_idx][0], &vu.mem[addr_byte], 16);
}

