// Helper to normalize float operands as per VU1 spec
// Denormals (exp 0) -> zero of same sign
// Inf/NaN (exp 0xFF) -> max float of same sign
static float normalize(float f) {
    uint32_t bits;
    std::memcpy(&bits, &f, 4);
    uint32_t exp = (bits >> 23) & 0xFF;
    if (exp == 0) {
        // Denormal or zero: return 0.0 with sign bit preserved
        bits &= 0x80000000;
    } else if (exp == 0xFF) {
        // Infinity or NaN: clamp to max float (0x7F7FFFFF) with sign
        bits = (bits & 0x80000000) | 0x7F7FFFFF;
    }
    float res;
    std::memcpy(&res, &bits, 4);
    return res;
}

// Helper to read a 32-bit little-endian word from memory
static uint32_t read_word(const uint8_t* mem, uint32_t byte_offset) {
    return (uint32_t)mem[byte_offset]
         | ((uint32_t)mem[byte_offset + 1] << 8)
         | ((uint32_t)mem[byte_offset + 2] << 16)
         | ((uint32_t)mem[byte_offset + 3] << 24);
}

