// Helper to normalize floats as per VU1 spec
static inline float normalize(float f) {
    uint32_t bits = *(uint32_t*)&f;
    uint32_t exp = bits & 0x7f800000;
    if (exp == 0) {
        // Denormal -> 0 of same sign
        return (bits & 0x80000000) ? -0.0f : 0.0f;
    }
    if (exp == 0x7f800000) {
        // Inf/NaN -> max float of same sign
        return (bits & 0x80000000) ? -3.402823466e+38f : 3.402823466e+38f;
    }
    return f;
}

// Helper to normalize arithmetic results
static inline float normalize_result(float f) {
    return normalize(f);
}

// Helper to load 32-bit float from memory (little-endian)
static inline float load_mem_float(const uint8_t* mem, uint32_t addr) {
    uint32_t bits = (uint32_t)mem[addr] |
                    ((uint32_t)mem[addr + 1] << 8) |
                    ((uint32_t)mem[addr + 2] << 16) |
                    ((uint32_t)mem[addr + 3] << 24);
    return *(float*)&bits;
}

// Helper to store 32-bit integer to memory (little-endian)
static inline void store_mem_int32(uint8_t* mem, uint32_t addr, uint32_t val) {
    mem[addr + 0] = val & 0xFF;
    mem[addr + 1] = (val >> 8) & 0xFF;
    mem[addr + 2] = (val >> 16) & 0xFF;
    mem[addr + 3] = (val >> 24) & 0xFF;
}

// Helper to load 16-bit integer from memory (little-endian, signed)
static inline int16_t load_mem_int16(const uint8_t* mem, uint32_t addr) {
    uint16_t val = (uint16_t)mem[addr] | ((uint16_t)mem[addr + 1] << 8);
    return (int16_t)val;
}

// Helper to store 16-bit integer to memory (little-endian)
static inline void store_mem_int16(uint8_t* mem, uint32_t addr, int16_t val) {
    mem[addr + 0] = val & 0xFF;
    mem[addr + 1] = (val >> 8) & 0xFF;
}

// Helper to get qword byte address with wrapping
static inline uint32_t get_qword_addr(const VuState& vu, int16_t qword_idx) {
    // qword_idx is already 16-bit signed, cast to uint16_t for wrapping
    uint16_t idx = (uint16_t)qword_idx;
    return idx * 16;
}

void stage(VuState &vu) {
    // 3e48: MUL.xyz vf26, vf5, vf14            RSQRT Q, vf0w, vf14w
    {
        // MUL.xyz vf26, vf5, vf14
        float vf5_x = normalize(vu.vf[5][0]);
        float vf5_y = normalize(vu.vf[5][1]);
        float vf5_z = normalize(vu.vf[5][2]);
        float vf14_x = normalize(vu.vf[14][0]);
        float vf14_y = normalize(vu.vf[14][1]);
        float vf14_z = normalize(vu.vf[14][2]);
        vu.vf[26][0] = normalize_result(vf5_x * vf14_x);
        vu.vf[26][1] = normalize_result(vf5_y * vf14_y);
        vu.vf[26][2] = normalize_result(vf5_z * vf14_z);
        // vf26.w unchanged

        // RSQRT Q, vf0w, vf14w
        // vf0.w is always 1.0
        float vf14_w = normalize(vu.vf[14][3]);
        vu.q = 1.0f / std::sqrt(vf14_w);
    }

    // 3e50: MULAx.x ACC, vf25, vf15x           ISW.x vi3, -1(vi14)
    {
        // MULAx.x ACC, vf25, vf15x
        float vf25_x = normalize(vu.vf[25][0]);
        float vf15_x = normalize(vu.vf[15][0]);
        vu.acc[0] = normalize_result(vf25_x * vf15_x);
        // ACC.y, z, w unchanged

        // ISW.x vi3, -1(vi14)
        // vi14 is 16-bit integer register
        int16_t vi14_val = (int16_t)vu.vi[14];
        int16_t base_qword = vi14_val - 1;
        uint32_t addr = get_qword_addr(vu, base_qword);
        // ISW.x stores 16-bit value (zero-extended) to word 0 (bytes 0-3)
        uint32_t store_val = (uint32_t)(vu.vi[3] & 0xFFFF);
        store_mem_int32(vu.mem, addr, store_val);
    }

    // 3e58: MADDAy.x ACC, vf25, vf15y          ILW.w vi3, 1006(vi8)
    {
        // MADDAy.x ACC, vf25, vf15y
        float vf25_x = normalize(vu.vf[25][0]);
        float vf15_y = normalize(vu.vf[15][1]);
        vu.acc[0] = normalize_result(vu.acc[0] + vf25_x * vf15_y);
        // ACC.y, z, w unchanged

        // ILW.w vi3, 1006(vi8)
        // vi8 is 16-bit integer register
        int16_t vi8_val = (int16_t)vu.vi[8];
        int16_t base_qword = vi8_val + 1006;
        uint32_t addr = get_qword_addr(vu, base_qword);
        // ILW.w loads from word 3 (bytes 12-15), takes low 16 bits, sign-extends
        uint32_t load_val = *(uint32_t*)&vu.mem[addr + 12]; // Unaligned access, but safe for bytes
        uint16_t low16 = load_val & 0xFFFF;
        vu.vi[3] = (int32_t)(int16_t)low16;
    }

    // 3e60: MADDz.x vf15, vf25, vf15z          NOP
    {
        // MADDz.x vf15, vf25, vf15z
        // MADD uses ACC as the accumulator: vf = ACC + a * b
        float vf25_x = normalize(vu.vf[25][0]);
        float vf15_z = normalize(vu.vf[15][2]);
        vu.vf[15][0] = normalize_result(vu.acc[0] + vf25_x * vf15_z);
        // vf15.y, z, w unchanged
    }

    // 3e68: MULAx.y ACC, vf25, vf26x           IADDIU vi7, vi0, 240
    {
        // MULAx.y ACC, vf25, vf26x
        float vf25_y = normalize(vu.vf[25][1]);
        float vf26_x = normalize(vu.vf[26][0]);
        vu.acc[1] = normalize_result(vf25_y * vf26_x);
        // ACC.x, z, w unchanged

        // IADDIU vi7, vi0, 240
        // vi0 is 0
        vu.vi[7] = 240; // Fits in 16-bit signed
    }

    // 3e70: MADDAy.y ACC, vf25, vf26y          NOP
    {
        // MADDAy.y ACC, vf25, vf26y
        float vf25_y = normalize(vu.vf[25][1]);
        float vf26_y = normalize(vu.vf[26][1]);
        vu.acc[1] = normalize_result(vu.acc[1] + vf25_y * vf26_y);
        // ACC.x, z, w unchanged
    }

    // 3e78: MADDz.y vf15, vf25, vf26z          IAND vi3, vi3, vi7
    {
        // MADDz.y vf15, vf25, vf26z
        // MADD uses ACC as the accumulator: vf = ACC + a * b
        float vf25_y = normalize(vu.vf[25][1]);
        float vf26_z = normalize(vu.vf[26][2]);
        vu.vf[15][1] = normalize_result(vu.acc[1] + vf25_y * vf26_z);
        // vf15.x, z, w unchanged

        // IAND vi3, vi3, vi7
        // vi registers are 16-bit
        uint16_t vi3_val = vu.vi[3] & 0xFFFF;
        uint16_t vi7_val = vu.vi[7] & 0xFFFF;
        uint16_t result = vi3_val & vi7_val;
        vu.vi[3] = (int32_t)(int16_t)result;
    }

    // 3e80: NOP                                LQ.xyzw vf6, 1007(vi8)
    {
        // LQ.xyzw vf6, 1007(vi8)
        int16_t vi8_val = (int16_t)vu.vi[8];
        int16_t base_qword = vi8_val + 1007;
        uint32_t addr = get_qword_addr(vu, base_qword);
        // Load 16 bytes (4 floats)
        vu.vf[6][0] = load_mem_float(vu.mem, addr);
        vu.vf[6][1] = load_mem_float(vu.mem, addr + 4);
        vu.vf[6][2] = load_mem_float(vu.mem, addr + 8);
        vu.vf[6][3] = load_mem_float(vu.mem, addr + 12);
    }

    // 3e88: NOP                                LQ.xyzw vf8, 16(vi8)
    {
        // LQ.xyzw vf8, 16(vi8)
        int16_t vi8_val = (int16_t)vu.vi[8];
        int16_t base_qword = vi8_val + 16;
        uint32_t addr = get_qword_addr(vu, base_qword);
        vu.vf[8][0] = load_mem_float(vu.mem, addr);
        vu.vf[8][1] = load_mem_float(vu.mem, addr + 4);
        vu.vf[8][2] = load_mem_float(vu.mem, addr + 8);
        vu.vf[8][3] = load_mem_float(vu.mem, addr + 12);
    }

    // 3e90: NOP                                LQ.xyzw vf5, 1011(vi8)
    {
        // LQ.xyzw vf5, 1011(vi8)
        int16_t vi8_val = (int16_t)vu.vi[8];
        int16_t base_qword = vi8_val + 1011;
        uint32_t addr = get_qword_addr(vu, base_qword);
        vu.vf[5][0] = load_mem_float(vu.mem, addr);
        vu.vf[5][1] = load_mem_float(vu.mem, addr + 4);
        vu.vf[5][2] = load_mem_float(vu.mem, addr + 8);
        vu.vf[5][3] = load_mem_float(vu.mem, addr + 12);
    }

    // 3e98: NOP                                LQ.xyzw vf7, 20(vi8)
    {
        // LQ.xyzw vf7, 20(vi8)
        int16_t vi8_val = (int16_t)vu.vi[8];
        int16_t base_qword = vi8_val + 20;
        uint32_t addr = get_qword_addr(vu, base_qword);
        vu.vf[7][0] = load_mem_float(vu.mem, addr);
        vu.vf[7][1] = load_mem_float(vu.mem, addr + 4);
        vu.vf[7][2] = load_mem_float(vu.mem, addr + 8);
        vu.vf[7][3] = load_mem_float(vu.mem, addr + 12);
    }

    // 3ea0: SUB.xyz vf14, vf6, vf16            WAITQ
    {
        // SUB.xyz vf14, vf6, vf16
        float vf6_x = normalize(vu.vf[6][0]);
        float vf6_y = normalize(vu.vf[6][1]);
        float vf6_z = normalize(vu.vf[6][2]);
        float vf16_x = normalize(vu.vf[16][0]);
        float vf16_y = normalize(vu.vf[16][1]);
        float vf16_z = normalize(vu.vf[16][2]);
        vu.vf[14][0] = normalize_result(vf6_x - vf16_x);
        vu.vf[14][1] = normalize_result(vf6_y - vf16_y);
        vu.vf[14][2] = normalize_result(vf6_z - vf16_z);
        // vf14.w unchanged

        // WAITQ
        // In C++, Q is already computed, so no action needed
    }

    // Exit
    vu.pc = 0x3ea8;
}
