// Helper to normalize floats as per VU1 spec
static inline float normalize(float f) {
    uint32_t bits = *(uint32_t*)&f;
    uint32_t exp = bits & 0x7f800000;
    if (exp == 0) {
        // Denormal -> 0 of same sign
        return (bits & 0x80000000) ? -0.0f : 0.0f;
    }
    if (exp == 0x7f800000) {
        // Inf/NaN -> max float of same sign
        return (bits & 0x80000000) ? -3.402823466e+38f : 3.402823466e+38f;
    }
    return f;
}

void stage(VuState &vu) {
    // 3ea8: MULAx.y ACC, vf25, vf7x            IADDIU vi8, vi8, 1
    {
        // MULAx.y ACC, vf25, vf7x
        // MULA does not read old ACC. x broadcast means vf7.x is broadcast to all dest lanes.
        // Destination mask .y writes only ACC.y
        float a = normalize(vu.vf[25][1]);
        float b = normalize(vu.vf[7][0]);
        vu.acc[1] = normalize(a * b);

        // IADDIU vi8, vi8, 1
        int16_t vi8_val = (int16_t)vu.vi[8];
        vu.vi[8] = (int32_t)(vi8_val + 1);
    }

    // 3eb0: MULq.xy vf15, vf15, Q              NOP   [Q = result of the DIV at 0x3e48]
    {
        // MULq.xy vf15, vf15, Q
        // q means use Q register instead of last operand.
        // Destination mask .xy writes vf15.x and vf15.y
        float q_val = normalize(vu.q);
        float f15_x = normalize(vu.vf[15][0]);
        float f15_y = normalize(vu.vf[15][1]);
        vu.vf[15][0] = normalize(f15_x * q_val);
        vu.vf[15][1] = normalize(f15_y * q_val);
    }

    // 3eb8: MUL.xyz vf13, vf14, vf14           IBEQ vi3, vi0, 0x3ed8
    {
        // MUL.xyz vf13, vf14, vf14
        float f14_x = normalize(vu.vf[14][0]);
        float f14_y = normalize(vu.vf[14][1]);
        float f14_z = normalize(vu.vf[14][2]);
        vu.vf[13][0] = normalize(f14_x * f14_x);
        vu.vf[13][1] = normalize(f14_y * f14_y);
        vu.vf[13][2] = normalize(f14_z * f14_z);

        // IBEQ vi3, vi0, 0x3ed8
        // vi0 is always 0
        bool taken = (vu.vi[3] == 0);
        if (taken) {
            vu.pc = 0x3ed8;
        } else {
            vu.pc = 0x3ec8;
        }
    }

    // 3ec0: MADDw.y vf31, vf7, vf14w           NOP   [delay slot of the branch above: executes before the jump, also when it is taken]
    {
        // MADDw.y vf31, vf7, vf14w
        // MADD reads old ACC. w broadcast means vf14.w is broadcast.
        // Destination mask .y writes only vf31.y
        float acc1 = normalize(vu.acc[1]);
        float f7_y = normalize(vu.vf[7][1]);
        float f14_w = normalize(vu.vf[14][3]);
        vu.vf[31][1] = normalize(acc1 + f7_y * f14_w);

        if (vu.pc == 0x3ed8) {
            return;
        }
    }

    // 3ec8: MULAz.w ACC, vf7, vf7z             B 0x3ee0
    {
        // MULAz.w ACC, vf7, vf7z
        // MULA does not read old ACC. z broadcast means vf7.z is broadcast.
        // Destination mask .w writes only ACC.w
        float f7_w = normalize(vu.vf[7][3]);
        float f7_z = normalize(vu.vf[7][2]);
        vu.acc[3] = normalize(f7_w * f7_z);
    }

    // 3ed0: MADDy.w vf31, vf7, vf15y           NOP   [delay slot of the branch above: executes before the jump, also when it is taken]
    {
        // MADDy.w vf31, vf7, vf15y
        // MADD reads old ACC. y broadcast means vf15.y is broadcast.
        // Destination mask .w writes only vf31.w
        float acc3 = normalize(vu.acc[3]);
        float f7_w = normalize(vu.vf[7][3]);
        float f15_y = normalize(vu.vf[15][1]);
        vu.vf[31][3] = normalize(acc3 + f7_w * f15_y);

        vu.pc = 0x3ee0;
    }
}
